import {installHoverPreview} from './hover-preview.mjs';
import {normalizeSettings,customizationBrief} from './settings.mjs';
import {planSession} from './session.mjs';
import {creatorActivity,curateVideos} from './activity.mjs';
import {SOURCES,TIERS,clean,normalizeLibrary,mergeLibraries,buildCreators,buildHomeFeed,filterVideos,formatDuration,cleanPreferences,exportLibrary} from './core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='picked-space.library.v2',OLD='picked-space.library.v1',PREF='picked-space.preferences.v1',CREATORS='picked-space.creators.v1';
let inactiveMonths=12;
let library={schemaVersion:1,title:'我的频道',owner:'我',videos:[]},policy={},prefs={},creatorPrefs={},feed=[],limit=40,current=null,pending=null,timer;
const initial=()=>({query:'',creator:'',tier:'all',source:'all',status:'all',duration:'all',includeRanking:true,showInactive:false,sort:'feed'});let state=initial();
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d;}catch{return d;}};
let settings=normalizeSettings(read('picked-space.settings.v1',{})),usingDemo=false,playMode='full';
const hoverPreview=installHoverPreview($('#cards'),{enabled:()=>settings.hoverPreview});
const pref=v=>prefs[v.key]||{},creator=v=>creatorPrefs[v.creatorKey]||{},creators=()=>library.followedCreators?.length?buildCreators(availableVideos(),{},library.followedCreators.filter(c=>state.showInactive||creatorActivity(c,{months:inactiveMonths})!=='inactive'&&!['unavailable','no-public-uploads'].includes(c.profileStatus))).filter(c=>state.showInactive||c.count>0):[];
const availableVideos=()=>curateVideos(library.videos,library.followedCreators,{months:inactiveMonths,showInactive:state.showInactive});
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function persist(){try{if(!usingDemo)localStorage.setItem(KEY,JSON.stringify(library));localStorage.setItem(PREF,JSON.stringify(prefs));localStorage.setItem(CREATORS,JSON.stringify(creatorPrefs));localStorage.removeItem(OLD);return true;}catch{toast('浏览器存储未保存成功，请导出数据备份');return false;}}
function rebuild(){feed=buildHomeFeed(availableVideos(),{},Math.random,{includeRanking:state.includeRanking});}
function list(){const videos=filterVideos(feed,state,prefs,creatorPrefs);return settings.hideWatched?videos.filter(v=>!pref(v).watched):videos;}
function counts(){return Object.fromEntries(Object.keys(SOURCES).map(s=>[s,availableVideos().filter(v=>v.sources.includes(s)).length]));}
function show(id){$(id).showModal();$('#sidebar').classList.remove('open');}
function navigation(){
 const cs=creators(),names={all:'随便看看',starred:'我留下的'};
 $('#main-nav').innerHTML=[['all','▦'],['starred','☆']].map(([key,icon])=>`<button class="nav-item ${state.status===key&&!state.creator?'active':''}" data-status="${key}"><span>${icon}</span><span>${names[key]}</span></button>`).join('');
 $('#creator-total').textContent=cs.length;$('#show-inactive').checked=state.showInactive;$('#inactive-months').value=String(inactiveMonths);
 $('.side-hint').textContent=`${inactiveMonths}个月未更新的频道默认隐藏；不改变B站关注。`;
 const q=$('#creator-search').value.trim().toLowerCase();$('#creator-nav').innerHTML=cs.filter(c=>c.name.toLowerCase().includes(q)).map(c=>`<button class="nav-item folder-item ${state.creator===c.key?'active':''}" data-creator="${esc(c.key)}"><span class="creator-dot">${esc(c.name.slice(0,1))}</span><span>${esc(c.name)}</span><span class="count">${c.count}</span></button>`).join('');
 document.title=library.title+' · 拾藏';const selected=cs.find(c=>c.key===state.creator),other=library.videos.find(v=>v.creatorKey===state.creator);const name=selected?.name||(state.creator?other?.author:'')||names[state.status]||'随便看看';
 $('#breadcrumb').textContent=name;$('#section-title').firstChild.textContent=name+' ';$('#creator-context').hidden=true;
 $('#time-filters').innerHTML=[['all','全部时长'],['short','10分钟内'],['medium','10–30分钟'],['long','30分钟以上']].map(([key,title])=>`<button class="pill ${state.duration===key?'active':''}" data-time="${key}" aria-pressed="${state.duration===key}">${title}</button>`).join('');
 const sc=counts();$('#scope-text').textContent=library.provenance?.scope||'来源范围尚未填写';$('#scope-counts').textContent=Object.entries(SOURCES).map(([key,name])=>name+'：'+sc[key]).join(' · ');
 updateResume();
}
function card(v){const p=pref(v);return `<article class="video-card"><button class="thumb-button" data-open="${v.key}" aria-label="播放：${esc(v.title)}"><div class="thumb-fallback"><span>${esc(v.author)}</span><strong>${esc(v.title)}</strong></div>${v.cover?`<img src="${esc(v.cover)}" alt="${esc(v.title)}" loading="lazy" referrerpolicy="no-referrer">`:''}${v.duration!==null?`<span class="duration">${formatDuration(v.duration)}</span>`:''}<span class="play-overlay"><b>▶</b></span>${p.watched?'<span class="watched-badge">已看</span>':''}</button><div class="card-info"><button class="card-title" data-open="${v.key}" title="${esc(v.title)}">${esc(v.title)}</button><div class="card-author"><button class="creator-inline" data-filter-creator="${esc(v.creatorKey)}">${esc(v.author)}</button><button class="mini-action ${p.starred?'on':''}" data-star="${v.key}" aria-label="留住：${esc(v.title)}">${p.starred?'★':'☆'}</button></div></div></article>`;}
function render(){hoverPreview.stop();navigation();$('#welcome').hidden=!!library.videos.length;const vs=list();$('#result-count').textContent=vs.length;$('#cards').innerHTML=vs.slice(0,limit).map(card).join('');$('#cards').querySelectorAll('img').forEach(i=>i.addEventListener('error',()=>{const tries=Number(i.dataset.retry||0);i.dataset.retry=String(tries+1);if(tries===0&&i.src.includes('@'))i.src=i.src.split('@')[0];else if(tries<3&&/i[012]\.hdslb\.com/.test(i.src))i.src=i.src.replace(/i[012]\.hdslb\.com/,'i'+(tries%3)+'.hdslb.com');else i.remove();}));$('#loading').hidden=true;$('#empty').hidden=!!vs.length;$('#load-more').hidden=vs.length<=limit;}
function reset(){state=initial();state.includeRanking=settings.includeRanking;$('#search').value='';$('#sort').value='feed';limit=40;rebuild();render();}
function patch(key,value){prefs[key]={...prefs[key],...value};persist();render();}
let sessionMinutes=30,planned=null,sessionQueue=[],sessionMode=false;
let progress=read('picked-space.progress.v1',{});
function storeProgress(){try{localStorage.setItem('picked-space.progress.v1',JSON.stringify(progress));}catch{}}
function saveProgress(part=Number($('#player-part').value)||1){const video=$('#player-area video');if(!current||!video||!Number.isFinite(video.duration)||video.currentTime<5)return;if(video.ended||video.currentTime>=video.duration-5){delete progress[current.key];}else progress[current.key]={position:video.currentTime,part,at:Date.now()};storeProgress();updateResume();}
function updateResume(){const allowed=new Set(availableVideos().map(v=>v.key));const entry=Object.entries(progress).filter(([k,p])=>allowed.has(k)&&!prefs[k]?.watched&&p.position>5).sort((a,b)=>b[1].at-a[1].at)[0],b=$('#resume-button');b.hidden=!entry;if(!entry)return;const v=library.videos.find(v=>v.key===entry[0]);b.dataset.key=v.key;b.innerHTML=`<span>↳ 接着上次看</span><strong>${esc(v.title)}</strong><small>看到 ${formatDuration(entry[1].position)}　▶</small>`;}
function updateQueue(){const q=$('#queue-status');q.hidden=!sessionMode;q.textContent=sessionMode?`私人放映 · 本条结束后${sessionQueue.length?'还有 '+sessionQueue.length+' 条 · 下一条：'+sessionQueue[0].title:'这组就看完了'}`:'';$('#next-random').textContent=sessionMode?(sessionQueue.length?'下一条 ▶':'结束放映'):'换一条 ▶';}
function makePlan(){const scope=list();planned=planSession(scope,{minutes:sessionMinutes,prefs});$('#session-title').textContent=`${sessionMinutes} 分钟，安排好了。`;$('#session-description').textContent=planned.videos.length?`${planned.videos.length} 条 · 合计 ${formatDuration(planned.total)} · 只选未看完、时长明确的视频，同组博主不重复${state.creator?'。当前只选了一个博主，所以安排一条。':'。'}`:'当前范围没有符合时间的未看视频。试试更长时间，或清除筛选。';$('#session-list').innerHTML=planned.videos.map(v=>`<li><span class="session-number">${planned.videos.indexOf(v)+1}</span><div><strong>${esc(v.title)}</strong><small>${esc(v.author)} · ${formatDuration(v.duration)}${v.sources.some(s=>s==='favorites'||s==='watchlater')?' · 你存下的':''}</small></div></li>`).join('');$('#session-start').disabled=!planned.videos.length;if(!$('#session-dialog').open)show('#session-dialog');}
$('#session-times').onclick=e=>{const b=e.target.closest('[data-minutes]');if(!b)return;sessionMinutes=Number(b.dataset.minutes);for(const button of $('#session-times').querySelectorAll('button')){button.classList.toggle('active',button===b);button.setAttribute('aria-pressed',String(button===b));}};
$('#session-plan').onclick=makePlan;$('#session-reroll').onclick=makePlan;$('#session-start').onclick=()=>{if(!planned?.videos.length)return;sessionMode=true;sessionQueue=[...planned.videos];$('#session-dialog').close();nextRandom();};$('#resume-dismiss').onclick=()=>{delete progress[$('#resume-button').dataset.key];storeProgress();updateResume();};$('#resume-button').onclick=()=>{sessionMode=false;sessionQueue=[];openVideo($('#resume-button').dataset.key);};window.addEventListener('pagehide',()=>saveProgress());
let playRequest=0;
async function loadNative(part=1){
 const v=current;if(!v)return;const request=++playRequest;
 const previous=$('#player-area video');if(previous){previous.pause();previous.removeAttribute('src');previous.load();}$('#player-area').replaceChildren();$('#player-status').textContent='正在取得本地播放流…';$('#retry-playback').hidden=true;$('#player-part').hidden=true;
 try{const r=await fetch('api/playback?'+new URLSearchParams({bvid:v.id,part:String(part)}));const info=await r.json();if(!r.ok)throw Error(info.error||'获取视频失败');if(request!==playRequest||current?.key!==v.key)return;
  if(!/^\/api\/media\/[a-zA-Z0-9-]+$/.test(info.src))throw Error('播放地址不正确');
  const video=document.createElement('video');video.controls=true;video.autoplay=true;video.playsInline=true;video.preload='metadata';video.src=info.src;video.setAttribute('aria-label','本地视频播放器');
  video.addEventListener('loadedmetadata',()=>{const saved=progress[v.key];if(saved?.part===part&&saved.position>5&&saved.position<video.duration-10)video.currentTime=saved.position;});let lastSave=0;video.addEventListener('timeupdate',()=>{if(video.currentTime-lastSave>=5||video.currentTime<lastSave){lastSave=video.currentTime;saveProgress(part);}});video.addEventListener('ended',()=>{prefs[v.key]={...pref(v),watched:true};delete progress[v.key];storeProgress();persist();if($('#auto-next').checked)nextRandom();else updateResume();});video.addEventListener('error',()=>{if(request===playRequest){$('#player-status').textContent='播放中断，可重试刷新地址';$('#retry-playback').hidden=false;}});
  $('#player-area').append(video);$('#player-status').textContent='本站直接播放 · '+info.quality+(info.pages.length>1?' · 分P '+part+'/'+info.pages.length:'');
  $('#player-part').innerHTML=info.pages.map(p=>`<option value="${p.page}">${p.page}. ${esc(p.part)}</option>`).join('');$('#player-part').value=String(part);$('#player-part').hidden=info.pages.length<2;
  video.play().catch(()=>{if(request===playRequest)$('#player-status').textContent='本站直接播放 · '+info.quality+' · 点击播放器开始';});
 }catch(e){if(request===playRequest){$('#player-status').textContent=e.message;$('#retry-playback').hidden=false;$('#player-area').innerHTML='<div class="player-error">暂时没能取得可播放的完整视频。<br>可重试，本站不会自动跳转。</div>';}}
}
function openVideo(key){saveProgress();const v=library.videos.find(x=>x.key===key);if(!v)return;current=v;$('#watch-title').textContent=v.title;$('#mini-title').textContent=v.title;$('#watch-meta').textContent=[v.author,v.duration===null?'时长未记录':formatDuration(v.duration),v.publishedAtLabel||'',v.ranking?`${v.ranking.name} #${v.ranking.rank}（${v.ranking.capturedAt}）`:''].filter(Boolean).join(' · ');$('#original-link').href=v.url;$('#note').value=pref(v).note||'';$('#note-status').textContent='笔记保存在本机';watchLabels();updateQueue();if(playMode!=='mini'&&!$('#watch-dialog').open)show('#watch-dialog');loadNative();}

function watchLabels(){if(!current)return;$('#watch-mark').textContent=pref(current).watched?'✓ 已看 · 改为未看':'✓ 标为已看';$('#watch-star').textContent=pref(current).starred?'★ 已特别收藏':'☆ 特别收藏';}
function nextRandom(){if(sessionQueue.length){const next=sessionQueue.shift();openVideo(next.key);return;}if(sessionMode){sessionMode=false;stopPlayback();toast('这组看完了。休息一下，或再安排一组。');return;}const vs=list().filter(v=>v.key!==current?.key);if(!vs.length){toast('当前筛选没有其他视频');return;}openVideo(buildHomeFeed(vs,{},Math.random,{includeRanking:state.includeRanking})[0].key);}
function clearImport(){pending=null;$('#import-report').textContent='';$('#validate-import').hidden=false;$('#apply-import').hidden=true;}
function validateImport(){try{const input=JSON.parse($('#import-text').value.trim().replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,''));const r=normalizeLibrary(input,policy);if(r.errors.length)throw new Error(r.errors.slice(0,8).join('\n'));if(!r.library.videos.length)throw new Error('没有可导入的公开B站视频。请让AI标注visibility为public，并排除私密来源。');const fresh=!library.videos.length||usingDemo;const m=fresh?{library:r.library,added:r.library.videos.length,updated:0}:mergeLibraries(library,r.library);if(!fresh)m.library.followedCreators=[...new Map([...(library.followedCreators||[]),...(r.library.followedCreators||[])].map(c=>[c.id,c])).values()];pending={input,result:r,merged:m};$('#import-report').className='import-report';$('#import-report').textContent=`有效${r.library.videos.length}条；新增${m.added}条，更新${m.updated}条，重复${r.duplicates}条。\n跳过：非B站${r.skipped.platform}条、私密${r.skipped.private}条、未确认公开${r.skipped.unverified}条。\n合并后${m.library.videos.length}条，原有笔记保留。`;$('#validate-import').hidden=true;$('#apply-import').hidden=false;}catch(e){pending=null;$('#import-report').className='import-report error';$('#import-report').textContent=e instanceof SyntaxError?'JSON格式不正确，请检查引号和逗号。':e.message;$('#apply-import').hidden=true;}}
function restorePersonal(input){for(const r of (Array.isArray(input)?input:input.videos)||[]){if(!r.personal)continue;const n=normalizeLibrary([r],policy).library.videos[0];if(n)prefs[n.key]={watched:r.personal.watched===true,starred:r.personal.starred===true,note:clean(r.personal.note,8000),...prefs[n.key]};}const keys=new Set(creators().map(c=>c.key));for(const [k,p] of Object.entries(input.creators||{})){if(keys.has(k)&&!creatorPrefs[k])creatorPrefs[k]={tier:TIERS.includes(p.tier)?p.tier:'',reason:clean(p.reason,500)};}}
const PROMPT=`请操作我本人已经登录的B站。只读取我指定范围的公开视频，不修改关注或收藏，不读取私密收藏夹，不导出Cookie、Token或密码。
先读取真实关注名单followedCreators（id和name），再从关注视频动态或博主投稿页读取近期公开视频，sources填["following"]。再读取我选择的公开收藏夹，sources填["favorites"]。再读取我授权的稍后再看列表，sources填["watchlater"]。如我要求加入榜单，记录真实榜单与日期，sources填["ranking"]；不要自行把热度当作精品或给博主评S/A/B/C。
保留真实标题、BV链接、作者名、作者UID（字符串）、封面、实际时长、发布日期；不可知字段留空，不编造。未能确认公开的条目不导入。同一视频可以属于多个来源和收藏夹，按BV合并。
格式：{"schemaVersion":1,"title":"我的频道","owner":"我","provenance":{"method":"AI读取本人授权的B站页面","scope":"真实读取的博主、收藏夹、日期、条数与未读范围","complete":false},"videos":[{"title":"真实标题","author":"真实作者","creatorId":"真实UID","url":"https://www.bilibili.com/video/BV...","cover":"实际封面地址","duration":null,"publishedAt":"","visibility":"public","sources":["following"],"collections":[],"tags":[]}]}
逐页或滚动读取实际卡片，核对数量和重复。排除推荐广告、页脚与失效视频，不要把首屏当全量。登录或验证码交给我处理。写成JSON文件导入，或合并写入dist/data/library.json，再点网页的刷新按钮。不要把登录凭证或私密内容放进网页数据。`;
$('#ai-prompt').textContent=PROMPT;
$('#main-nav').onclick=e=>{const b=e.target.closest('[data-status]');if(b){state.status=b.dataset.status;state.creator='';limit=40;render();$('#sidebar').classList.remove('open');}};
$('#creator-nav').onclick=e=>{const b=e.target.closest('[data-creator]');if(b){state.creator=b.dataset.creator;state.status='all';limit=40;render();$('#sidebar').classList.remove('open');}};$('#creator-search').oninput=navigation;
$('#time-filters').onclick=e=>{const b=e.target.closest('[data-time]');if(b){state.duration=b.dataset.time;limit=40;render();}};$('#search').oninput=e=>{state.query=e.target.value;limit=40;render();};$('#sort').onchange=e=>{state.sort=e.target.value;render();};$('#reshuffle').onclick=()=>{rebuild();limit=40;render();toast('已重新挑选这批内容');};$('#shuffle-button').onclick=()=>{sessionMode=false;sessionQueue=[];nextRandom();};$('#next-random').onclick=nextRandom;$('#retry-playback').onclick=()=>loadNative(Number($('#player-part').value)||1);$('#player-part').onchange=e=>loadNative(Number(e.target.value));$('#load-more').onclick=()=>{limit+=40;render();};$('#empty-action').onclick=()=>{reset();};
$('#cards').onclick=e=>{const b=e.target.closest('[data-open],[data-star],[data-filter-creator]');if(!b)return;if(b.dataset.open){sessionMode=false;sessionQueue=[];openVideo(b.dataset.open);}else if(b.dataset.star)patch(b.dataset.star,{starred:!prefs[b.dataset.star]?.starred});else if(b.dataset.watch)patch(b.dataset.watch,{watched:!prefs[b.dataset.watch]?.watched});else{state.creator=b.dataset.filterCreator;render();}};
$('#import-button').onclick=()=>{$('#profile-dialog').close();clearImport();show('#import-dialog');};$('#import-text').oninput=clearImport;$('#validate-import').onclick=validateImport;$('#apply-import').onclick=()=>{if(!pending)return;library=pending.merged.library;usingDemo=false;if(pending.input.settings){settings=normalizeSettings(pending.input.settings);applySettings();}restorePersonal(pending.input);prefs=cleanPreferences(prefs,library);persist();$('#import-dialog').close();reset();toast('内容已合并导入');};$('#pick-file').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>30*1024*1024){toast('请把文件拆成30MB以内');return;}$('#import-text').value=await f.text();clearImport();validateImport();e.target.value='';};
for(const id of ['#guide-side','#guide-footer','#open-guide'])$(id).onclick=()=>{$('#ai-prompt').textContent=customizationBrief(settings)+'\n'+PROMPT;show('#guide-dialog');};$('#copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText($('#ai-prompt').textContent);toast('已复制AI导入提示词');}catch{toast('请手动选择上方提示词复制');}};$('#scope-button').onclick=()=>{$('#profile-dialog').close();show('#scope-dialog');};
$('#export-button').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify({...exportLibrary(library,prefs,creatorPrefs),settings},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=`拾藏-公开B站-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);toast('已请求导出公开B站内容与笔记');};
$('#refresh-button').onclick=async()=>{try{const r=await fetch('data/library.json',{cache:'no-store'});if(!r.ok)throw new Error('请先让AI保存本地内容文件');const n=normalizeLibrary(await r.json(),policy);if(n.errors.length)throw new Error(n.errors[0]);library=mergeLibraries(normalizeLibrary(library,policy).library,n.library).library;prefs=cleanPreferences(prefs,library);persist();rebuild();render();toast('已刷新本地内容并排除非公开范围');}catch(e){toast(e.message);}};
$('#watch-mark').onclick=()=>{patch(current.key,{watched:!pref(current).watched});watchLabels();};$('#watch-star').onclick=()=>{patch(current.key,{starred:!pref(current).starred});watchLabels();};$('#save-note').onclick=()=>{patch(current.key,{note:clean($('#note').value,8000)});$('#note-status').textContent='已保存到本机';};$('#player-fullscreen').onclick=async()=>{try{await $('#player-area').requestFullscreen();}catch{toast('浏览器未进入全屏，可使用播放器自己的全屏按钮');}};
for(const b of document.querySelectorAll('.close-dialog'))b.onclick=()=>b.closest('dialog').close();$('#watch-dialog').addEventListener('close',()=>{if(!$('#watch-dialog').open&&playMode!=='mini')stopPlayback();});$('#inactive-months').onchange=e=>{inactiveMonths=Number(e.target.value);settings.inactiveMonths=inactiveMonths;applySettings();localStorage.setItem('picked-space.activity.v1',JSON.stringify({months:inactiveMonths}));state.creator='';limit=40;rebuild();render();};$('#show-inactive').onchange=e=>{state.showInactive=e.target.checked;state.creator='';limit=40;rebuild();render();};$('#menu-button').onclick=()=>$('#sidebar').classList.toggle('open');$('#profile-button').onclick=openSettings;
function openSettings(){ $('#space-title').value=library.title;$('#owner-name').value=library.owner;$('#layout-columns').value=String(settings.columns);$('#hover-enabled').checked=settings.hoverPreview;$('#ranking-enabled').checked=settings.includeRanking;$('#hide-watched').checked=settings.hideWatched;$('#my-interests').value=settings.interests;$('#my-request').value=settings.request;show('#profile-dialog');}
function formSettings(){return normalizeSettings({...settings,columns:Number($('#layout-columns').value),hoverPreview:$('#hover-enabled').checked,includeRanking:$('#ranking-enabled').checked,hideWatched:$('#hide-watched').checked,interests:$('#my-interests').value,request:$('#my-request').value,inactiveMonths});}
function applySettings(){inactiveMonths=settings.inactiveMonths;state.includeRanking=settings.includeRanking;document.documentElement.style.setProperty('--desktop-columns',settings.columns);try{localStorage.setItem('picked-space.settings.v1',JSON.stringify(settings));}catch{} }
$('#save-profile').onclick=()=>{library.title=clean($('#space-title').value,80)||'我的频道';library.owner=clean($('#owner-name').value,60)||'我';settings=formSettings();applySettings();persist();rebuild();render();$('#profile-dialog').close();};
function downloadFile(name,body,type='text/markdown;charset=utf-8'){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}
$('#export-brief').onclick=()=>downloadFile('我的拾藏需求.md',customizationBrief(formSettings()));
$('#welcome-setup').onclick=openSettings;$('#welcome-import').onclick=()=>{clearImport();show('#import-dialog');};$('#welcome-demo').onclick=async()=>{try{const r=await fetch('data/library.sample.json');if(!r.ok)throw Error();library=normalizeLibrary(await r.json()).library;usingDemo=true;reset();toast('正在浏览示例，导入自己的内容后会替换示例');}catch{toast('未能加载示例');}};
function stopPlayback(){saveProgress();playRequest++;const video=$('#player-area video');video?.pause();video?.removeAttribute('src');video?.load();$('#player-area').replaceChildren();current=null;playMode='full';$('#full-stage').append($('#player-area'));$('#mini-player').hidden=true;document.body.classList.remove('has-mini');if($('#watch-dialog').open)$('#watch-dialog').close();render();}
$('#minimize-player').onclick=()=>{if(!current)return;playMode='mini';$('#mini-stage').append($('#player-area'));$('#mini-player').hidden=false;document.body.classList.add('has-mini');$('#watch-dialog').close();};
$('#restore-player').onclick=()=>{playMode='full';$('#full-stage').append($('#player-area'));$('#mini-player').hidden=true;document.body.classList.remove('has-mini');show('#watch-dialog');};$('#stop-mini').onclick=stopPlayback;$('#mini-toggle').onclick=()=>{const v=$('#player-area video');if(v){if(v.paused)v.play().catch(()=>toast('请点击播放器继续'));else v.pause();}};$('#mini-next').onclick=nextRandom;
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='/'&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus();}if(e.key.toLowerCase()==='n'&&$('#watch-dialog').open)nextRandom();});
async function boot(){try{const activitySetting=read('picked-space.activity.v1',{});if(!localStorage.getItem('picked-space.settings.v1')&&[3,6,12,24].includes(activitySetting.months))settings.inactiveMonths=activitySetting.months;applySettings();try{const p=await fetch('data/policy.json',{cache:'no-store'});if(p.ok)policy=await p.json();}catch{}let r=await fetch('data/library.json',{cache:'no-store'});const seeded=r.ok;const base=normalizeLibrary(seeded?await r.json():{schemaVersion:1,videos:[]},policy);if(base.errors.length)throw new Error(base.errors[0]);const cache=read(KEY,null)||read(OLD,null);library=base.library;if(cache){const n=normalizeLibrary(cache,policy);library=mergeLibraries(base.library,n.library).library;library.title=n.library.title;library.owner=n.library.owner;if(seeded){library.revision=base.library.revision;library.provenance=base.library.provenance;library.followedCreators=base.library.followedCreators;}}prefs=cleanPreferences(read(PREF,{}),library);const validCreators=new Set(buildCreators(library.videos,creatorPrefs,library.followedCreators).map(c=>c.key));creatorPrefs=Object.fromEntries(Object.entries(read(CREATORS,{})).filter(([k])=>validCreators.has(k)).map(([k,v])=>[k,{tier:TIERS.includes(v?.tier)?v.tier:'',reason:clean(v?.reason,500)}]));persist();rebuild();render();}catch(e){$('#loading').hidden=true;rebuild();render();toast(e.message);}}
boot();
